    q=qxy[[3,0,1,2]]
    for off in ([0,0,.0],[0,0,.02],[0,-.03,.02],[0,.03,.02]):
     contact=p+off; pre=contact-app*.10
     if s.ik(contact,q)['success'] and s.ik(pre,q)['success']:
      found.append((rx,ry,rz,app,finger,q,contact,pre))
 print('found',len(found))
